insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'en', 'AG1 Magazine basket', 'Size: 22cm x 35cm, h 25cm', 'Each basket is unique. Pinumu Pasaule works with natural willow wicker, so twig marks and insect bites can appear without affecting quality. Basket sizes may vary by approximately 2 to 3 centimeters. Peeled, unpeeled and stained willow wicker are used, and the exact wicker combinations may differ from the photographs.', 'Handwoven willow wicker, magazine basket', 'Home-grown peeled and unpeeled willow wicker', 'Handwoven wickerwork' from public.products p where p.slug = 'pinumu-pasaule-ag1-avizu-grozs'
on conflict (product_id, locale) do update set
  name = excluded.name,
  description = excluded.description,
  story = excluded.story,
  craft = excluded.craft,
  materials = excluded.materials,
  technique = excluded.technique;

insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'de', 'AG1 Zeitungskorb', 'Größe: 22cm x 35cm, h 25cm', 'Jeder Korb ist ein Unikat. Pinumu Pasaule arbeitet mit natürlicher Weide, daher können Zweigspuren und kleine Insektenstellen sichtbar sein, ohne die Qualität zu beeinträchtigen. Die Korbgrößen können um etwa 2 bis 3 Zentimeter variieren. Verwendet werden geschälte, ungeschälte und gebeizte Weidenruten; die genaue Kombination kann von den Fotos abweichen.', 'Handgeflochtene Weide, Zeitungskorb', 'Selbst angebaute geschälte und ungeschälte Weidenruten', 'Handgeflochtenes Flechtwerk' from public.products p where p.slug = 'pinumu-pasaule-ag1-avizu-grozs'
on conflict (product_id, locale) do update set
  name = excluded.name,
  description = excluded.description,
  story = excluded.story,
  craft = excluded.craft,
  materials = excluded.materials,
  technique = excluded.technique;

