insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'en', 'KG2 Mushroom basket', 'Size: 39cm x 30cm, h 25cm', 'Each basket is unique. Pinumu Pasaule works with natural willow wicker, so twig marks and insect bites can appear without affecting quality. Basket sizes may vary by approximately 2 to 3 centimeters. Peeled, unpeeled and stained willow wicker are used, and the exact wicker combinations may differ from the photographs.', 'Handwoven willow wicker, mushroom basket', 'Home-grown peeled and unpeeled willow wicker', 'Handwoven wickerwork' from public.products p where p.slug = 'pinumu-pasaule-kg2-senu-grozs'
