insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'en', 'PL2 Wicker lamp', 'It is possible to make according to individual sizes Sample size: D 25cm, h 40cm. Price 90.00EUR+VAT', 'Each basket is unique. Pinumu Pasaule works with natural willow wicker, so twig marks and insect bites can appear without affecting quality. Basket sizes may vary by approximately 2 to 3 centimeters. Peeled, unpeeled and stained willow wicker are used, and the exact wicker combinations may differ from the photographs.', 'Handwoven willow wicker, wicker lamp', 'Home-grown peeled and unpeeled willow wicker', 'Handwoven wickerwork' from public.products p where p.slug = 'pinumu-pasaule-pl2-lampas-abazurs'
on conflict (product_id, locale) do update set
  name = excluded.name,
  description = excluded.description,
  story = excluded.story,
  craft = excluded.craft,
  materials = excluded.materials,
  technique = excluded.technique;

insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'de', 'PL2 Flechtlampe', 'Kann nach individuellen Maßen gefertigt werden Beispielgröße: D 25cm, h 40cm. Preis 90.00EUR+MwSt.', 'Jeder Korb ist ein Unikat. Pinumu Pasaule arbeitet mit natürlicher Weide, daher können Zweigspuren und kleine Insektenstellen sichtbar sein, ohne die Qualität zu beeinträchtigen. Die Korbgrößen können um etwa 2 bis 3 Zentimeter variieren. Verwendet werden geschälte, ungeschälte und gebeizte Weidenruten; die genaue Kombination kann von den Fotos abweichen.', 'Handgeflochtene Weide, Flechtlampe', 'Selbst angebaute geschälte und ungeschälte Weidenruten', 'Handgeflochtenes Flechtwerk' from public.products p where p.slug = 'pinumu-pasaule-pl2-lampas-abazurs'
on conflict (product_id, locale) do update set
  name = excluded.name,
  description = excluded.description,
  story = excluded.story,
  craft = excluded.craft,
  materials = excluded.materials,
  technique = excluded.technique;

