insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'en', 'PP5 Wicker tray', 'Sizes: 28cm x 20cm, h 6cm. Price 15.00 EUR+VAT 31cm x 24cm, h 7cm. Price 19.00 EUR+VAT 35cm x 33cm, h 7cm. Price 25.00 EUR+VAT', 'Each basket is unique. Pinumu Pasaule works with natural willow wicker, so twig marks and insect bites can appear without affecting quality. Basket sizes may vary by approximately 2 to 3 centimeters. Peeled, unpeeled and stained willow wicker are used, and the exact wicker combinations may differ from the photographs.', 'Handwoven willow wicker, wicker tray', 'Home-grown peeled and unpeeled willow wicker', 'Handwoven wickerwork' from public.products p where p.slug = 'pinumu-pasaule-pp5-paplate-sirds-forma'
