  name = excluded.name,
  description = excluded.description,
  story = excluded.story,
  craft = excluded.craft,
  materials = excluded.materials,
  technique = excluded.technique;

insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique)
select p.id, 'de', 'PP5 Flechttablett', 'Größen: 28cm x 20cm, h 6cm. Preis 15.00 EUR+MwSt. 31cm x 24cm, h 7cm. Preis 19.00 EUR+MwSt. 35cm x 33cm, h 7cm. Preis 25.00 EUR+MwSt.', 'Jeder Korb ist ein Unikat. Pinumu Pasaule arbeitet mit natürlicher Weide, daher können Zweigspuren und kleine Insektenstellen sichtbar sein, ohne die Qualität zu beeinträchtigen. Die Korbgrößen können um etwa 2 bis 3 Zentimeter variieren. Verwendet werden geschälte, ungeschälte und gebeizte Weidenruten; die genaue Kombination kann von den Fotos abweichen.', 'Handgeflochtene Weide, Flechttablett', 'Selbst angebaute geschälte und ungeschälte Weidenruten', 'Handgeflochtenes Flechtwerk' from public.products p where p.slug = 'pinumu-pasaule-pp5-paplate-sirds-forma'
on conflict (product_id, locale) do update set
